"""Generate New York from the shared UI with separate, source-reviewed state data."""
import copy
import json
import re
from pa_edition import BASE, replace_line

def new_york_resources(root, ohio):
    ids = json.loads((root / 'data/public/federal-resource-ids.json').read_text())
    by_id = {r['program_id']: r for r in ohio}
    shared = []
    for id in ids:
        r = copy.deepcopy(by_id[id])
        r.update(service_area=['National'], state='shared')
        shared.append(r)
    return (shared + json.loads((root / 'data/public/ny-programs.json').read_text())
            + json.loads((root / 'data/public/ny-regional-referrals.json').read_text()))

def make_ny(html, resources, counties):
    html = replace_line(html, 'const DATA=', 'const DATA=[];')
    html = replace_line(html, 'const COUNTIES=', 'const COUNTIES=[];')
    html = html.replace('Ohio', 'New York').replace('All 88', 'All 62').replace('all 88', 'all 62')
    html = html.replace('<option value="OH">New York</option>', '<option value="OH">Ohio</option>')
    html = html.replace('Choose an New York county', 'Choose a New York county')
    html = html.replace("'ohio'", "'new york'").replace("const STATE='OH';", "const STATE='NY';")
    # New York is also Manhattan's county name, so it must never mean statewide.
    html = replace_line(html, 'const national=', "const national=a=>['statewide','national','federal'].includes(a.toLowerCase());")
    html = html.replace('href="' + BASE + '"', 'href="' + BASE + 'ny.html"').replace('property="og:url" content="' + BASE + '"', 'property="og:url" content="' + BASE + 'ny.html"')
    html = html.replace('assets/share-preview.png', 'assets/vhg-logo.png').replace('content="1200"', 'content="715"').replace('content="630"', 'content="715"')
    html = html.replace('href="share.html"', 'href="share-ny.html"')
    html = html.replace('href="prototype-data.json"', 'href="data/public/new-york-resources.json"').replace('href="data/public/ohio-county-veterans-offices.json"', 'href="data/public/new-york-county-veterans-offices.json"')
    html = html.replace('county veterans offices', 'county and city veterans contacts').replace('county veterans office', 'veterans referral contact')
    html = html.replace('veterans referral contact contacts', 'veterans referral contacts')
    html = html.replace('Browse contacts for all 62 county and city veterans contacts', 'Browse veterans referral contacts for all 62 counties')
    html = html.replace('Choose a New York county</label>', 'Choose a New York county or NYC borough</label>')
    html = html.replace('Most phones come from New York AMVETS’ 2025–2026 directory.', 'Phones come from official state, county and city pages. NYC uses citywide intake; Essex uses a state benefits office.')
    html = html.replace('Statewide edition · Updated', 'New York edition · Updated')
    html = html.replace('New York’s waiver rule specifies proposal and approval requirements; VA and other funders have their own processes.', 'Ask your New York service coordinator or local funding administrator about assessment, written approval, owner consent and accepted providers.')
    html = html.replace('https://codes.ohio.gov/ohio-administrative-code/rule-5160-44-13', 'https://hcr.ny.gov/access-home').replace('New York home modification authorization and provider rules', 'New York Access to Home program requirements')
    html = re.sub(r'<div class="coverage notice">.*?</div>', '<div class="coverage notice"><strong>New York coverage:</strong> Veterans referral contacts and matched local aging offices for all 62 counties, including NYC’s five boroughs. NYC veterans intake is citywide, and Essex uses a state benefits office. Ombudsman help uses statewide routing. Published sources are reviewed, not telephone-confirmed. Local posts, repair providers and funding availability are still being researched.</div>', html, count=1)
    priority = ['ny-claims','ny-connects','ny-aging-directory','ny-eisep','ny-ombudsman','ny-hiicap','r02-aid-attendance-housebound','r02-va-pension','r02-survivors-pension','r02-dic','r02-va-health-enrollment','ny-nhtd','ny-traid','va-accredited-help']
    routes = dict(
        benefits=['r02-aid-attendance-housebound','r02-va-pension','r02-disability-increase','r02-pension-medicaid-rule','r02-survivors-pension','r02-dic','ny-claims','ny-hiicap','ny-blind-annuity','va-accredited-help'],
        survivors=['r02-survivors-pension','r02-dic','r02-aid-attendance-housebound','r02-va-burial','ny-claims','ny-blind-annuity','va-accredited-help','nara-discharge-records'],
        care=['r02-va-health-enrollment','va-location-finder','r02-va-cnh','r02-va-clc','r02-general-caregiver','r02-family-caregiver','r02-hospice','r02-palliative','ny-caregiver','ny-nhtd'],
        rights=['ny-ombudsman','ny-disability-rights','ny-connects'],
        local=['ny-connects','ny-aging-directory','ny-eisep','ny-caregiver','ny-nhtd','ny-traid','ny-independent-living'],
        housing=['va-housing-help','nara-discharge-records','va-location-finder','va-accredited-help','ny-access-home','ny-access-heroes','ny-restore'])
    topics = dict(daily=['ny-connects','ny-aging-directory','ny-eisep','ny-caregiver','ny-nhtd','ny-independent-living'],accessibility=['ny-access-home','ny-restore','ny-traid','ny-nhtd','ny-independent-living'],vision=['ny-vision','ny-traid'],hearing=['ny-relay','ny-traid'],memory=['alz-dementia-support','ny-caregiver','ny-eisep'],costs=['ny-hiicap','ny-eisep','ny-connects'],rights=['ny-disability-rights','ny-ombudsman','ny-connects'])
    for name, value in [('priority',priority),('routes',routes),('seniorTopics',topics)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value)+';')
    html = replace_line(html, 'routes.accessibility=', "routes.accessibility=['va-hisa','va-sah','va-sha','va-tra','ny-access-home','ny-access-heroes','ny-restore','ny-traid','ny-nhtd','ny-independent-living','va-location-finder','ny-connects',...DATA.filter(x=>x.regional_role==='aging_agency').map(x=>x.program_id)];")
    html = replace_line(html, 'routes.seniors=', "routes.seniors=[...new Set(Object.values(seniorTopics).flat()),...DATA.filter(x=>x.regional_role).map(x=>x.program_id),'cms-care-compare'];")
    for prefix, text in [('function officeCard(',OFFICE_JS),('function renderOfficeList()',OFFICE_LIST_JS),('function renderCounty()',COUNTY_JS),('function renderSeniorGuide()',SENIOR_JS),('function renderAccessibility()',ACCESS_JS),('function audience(',AUDIENCE_JS)]:
        html = replace_line(html, prefix, text)
    html = html.replace("o.textContent=c.county+' County'", "o.textContent=c.county+' County'+(c.county_aliases?' ('+c.county_aliases.join(', ')+')':'')")
    # Resolve borough aliases only within New York; shared links use canonical county names.
    html = html.replace("if(COUNTIES.some(c=>c.county===params.get('county')))", "const countyAlias=COUNTIES.find(c=>(c.county_aliases||[]).some(a=>a.toLowerCase()===(params.get('county')||'').toLowerCase()));if(countyAlias)params.set('county',countyAlias.county);if(COUNTIES.some(c=>c.county===params.get('county')))")
    for name,value in [('DATA',resources),('COUNTIES',counties)]:
        html = replace_line(html, 'const '+name+'=', 'const '+name+'='+json.dumps(value,ensure_ascii=True).replace('<','\\u003c')+';')
    return html

OFFICE_JS = """function officeCard(c){return `<article class="office-card"><span class="badge">${c.office_type==='city'?'NYC veterans intake':c.office_type==='state'?'State benefits office':'County veterans office'}</span><h2>${esc(c.county)} County${c.county_aliases?' ('+esc(c.county_aliases.join(', '))+')':''}</h2><p><strong>${esc(c.organization)}</strong><br>${phoneLink(c.phone)}</p><p>Ask for a benefits screening, claims assistance and referral support. Ask about remote appointments if travel is difficult.</p>${c.note?'<p class="small">'+esc(c.note)+'</p>':''}<p class="meta">Phone published on an official website · Reviewed ${esc(c.reviewed_on)}</p><div class="links"><a href="${esc(sourceURL(c))}" target="_blank" rel="noopener noreferrer">Contact source ↗</a></div></article>`}"""
OFFICE_LIST_JS = """function renderOfficeList(){const q=$('office-search').value.toLowerCase().trim();const rows=COUNTIES.filter(c=>[c.county,...(c.county_aliases||[])].some(n=>n.toLowerCase().includes(q)));$('office-list').innerHTML=rows.map(c=>`<div class="office-row"><button data-county="${esc(c.county)}">${esc(c.county)} County${c.county_aliases?' ('+esc(c.county_aliases.join(', '))+')':''}</button>${phoneLink(c.phone)}<p><a href="${esc(sourceURL(c))}" target="_blank" rel="noopener noreferrer">Official contact source ↗</a></p></div>`).join('')||'<p>No matching county. Try a shorter name.</p>';document.querySelectorAll('[data-county]').forEach(b=>b.onclick=()=>{$('county').value=b.dataset.county;render();$('county-start').scrollIntoView({behavior:'smooth'})})}"""
COUNTY_JS = """function renderCounty(){$('print-handoff-status').textContent='';const c=COUNTIES.find(c=>c.county===$('county').value);$('print-county').textContent=c?c.county+' County, New York':'New York statewide resources';if(!c){$('county-panel').innerHTML='<p class="meta">Choose a county or NYC borough for veterans help, a local aging contact, statewide ombudsman routing and a printable handoff.</p>';return}const aging=DATA.find(x=>x.regional_role==='aging_agency'&&x.service_area.includes(c.county));$('county-panel').innerHTML='<div class="contact-grid">'+officeCard(c)+'<article><h2>More help for '+esc(c.county)+' County</h2><h3>Local aging and community support</h3><p><strong>'+esc(aging.organization)+'</strong><br>'+phoneLink(aging.public_contact.phone)+'</p>'+(aging.public_contact.local_short_code?'<p class="small">Within NYC, dial 311 and ask for NYC Aging. The full number above is for callers outside the five boroughs.</p>':'')+'<p>Ask about meals, transportation, caregiving, assessment and support at home. Military service is not required.</p><p class="meta"><a href="'+esc(aging.official_url)+'" target="_blank" rel="noopener">Official aging contact source</a> · '+esc(labels[aging.verification.record_status])+' · '+esc(aging.verification.last_reviewed_on)+'</p><h3>Statewide ombudsman routing</h3><p>'+phoneLink('855-582-6769')+'</p><p>Give the facility county and ask for the local ombudsman. For immediate danger, call 911.</p><p><a href="'+esc(DATA.find(x=>x.program_id==='ny-ombudsman').official_url)+'" target="_blank" rel="noopener">Official ombudsman contact source</a></p><h3>NY Connects: all ages and disabilities</h3><p>'+phoneLink('800-342-9871')+'</p><p class="meta">Published referrals are not telephone-confirmed. Confirm intake, eligibility and availability.</p></article></div>'}"""
SENIOR_JS = """function renderSeniorGuide(){const active=route==='seniors';$('seniors-guide').hidden=!active;$('community-guide').hidden=route!=='community';$('county-panel').hidden=['accessibility','seniors','community'].includes(route);if(active){$('county-title').textContent='Choose your New York county or NYC borough';$('county-intro').textContent='Find your local aging office. NY Connects also routes people of all ages and disabilities. Military service is not required.'}if(route==='community'){$('county-title').textContent='Find New York community connections';$('county-intro').textContent='Use official post locators while local post contacts are being researched.'}if(!active)return;const county=$('county').value,agency=DATA.find(x=>x.regional_role==='aging_agency'&&x.service_area.includes(county));$('seniors-contact').innerHTML='<h3>Start with NY Connects or your local aging office</h3><p><strong>NY Connects statewide routing</strong><br>'+phoneLink('800-342-9871')+'</p>'+(agency?'<p><strong>'+esc(agency.organization)+'</strong><br>'+phoneLink(agency.public_contact.phone)+'</p>'+(agency.public_contact.local_short_code?'<p>Within NYC, dial 311 and ask for NYC Aging; the full number is for callers outside NYC.</p>':'')+'<p><a href="'+esc(agency.official_url)+'" target="_blank" rel="noopener">Local contact source</a> · '+esc(labels[agency.verification.record_status])+' · '+esc(agency.verification.last_reviewed_on)+'</p>':'<p>Choose a county above for its matched aging office.</p>')+'<p>Describe what makes daily life difficult and ask for assessment and the next referral. Many aging programs focus on age 60+; NY Connects serves broader disability needs.</p>';const topic=$('senior-topic').value;const guidance={daily:'Ask about meals, transport, personal care, caregiver support and EISEP assessment. Medicaid-supported services have separate screening and eligibility.',accessibility:'Ask about assessment, TRAID device loans and a funded Access to Home local administrator. RESTORE serves qualifying emergency repairs for older homeowners. Confirm funding and written approval before work.',vision:'Ask the Commission for the Blind for your district office and the appropriate vision-related support assessment. Program criteria apply; a diagnosis alone does not establish eligibility.',hearing:'Use New York Relay for accessible telephone calls. Ask TRAID about device demonstrations and loans. These routes do not guarantee payment for hearing aids.',memory:'Contact the Alzheimer’s Association for dementia and caregiver support. Ask your aging office about respite and help at home; seek clinical evaluation for new memory concerns.',costs:'HIICAP provides Medicare counseling and help understanding savings programs. Ask NY Connects about local assessment and care-cost referrals.',rights:'Contact the ombudsman about long-term-care resident concerns and Disability Rights New York about disability access and rights. Ask about intake, consent and follow-up.'};$('senior-guidance').innerHTML='<strong>'+(topic?'Your next step':'Choose a need, then make a referral')+'</strong><p>'+esc(guidance[topic]||'Choose a need to narrow the referrals. These routes do not require military service. Confirm eligibility and current availability with the provider.')+'</p>'}"""
AUDIENCE_JS = """function audience(x){if(/survivors|r02-dic/.test(x.program_id))return 'Surviving spouses and other qualifying survivors';if(/aid-attendance/.test(x.program_id))return 'Qualifying veterans and survivors who need daily help';if(x.program_id==='ny-eisep')return 'New York residents age 60+ with assessed home-support needs';if(x.program_id==='ny-restore')return 'Qualifying homeowners age 60+';if(/ombudsman/.test(x.program_id))return 'Residents of nursing homes, assisted living and adult care facilities';if(/nara/.test(x.program_id))return 'Veterans and eligible records requesters';return null}"""
ACCESS_JS = """function renderAccessibility(){const active=route==='accessibility';$('accessibility-guide').hidden=!active;$('county-panel').hidden=active;$('county-title').textContent=active?'Choose where help is needed':'Your first local contact';$('county-intro').textContent=active?'Choose a New York county or NYC borough for local referral contacts.':'Veterans contacts can help with benefits and referral screening. Ask which office should handle a resident who recently moved.';if(!active)return;const veteran=$('access-veteran').value,home=$('access-home').value,coverage=$('access-waiver').value,county=$('county').value,office=COUNTIES.find(c=>c.county===county),aging=DATA.find(x=>x.regional_role==='aging_agency'&&x.service_area.includes(county)),va=veteran==='yes',newHome=home==='new';const primary=coverage==='waiver'?'Your service coordinator':va?(newHome?'VA adapted housing team':'VA Prosthetics and your care team'):'NY Connects: aging and disability routing';const action=coverage==='waiver'?'Ask for an access assessment and written authorization through your service plan.':va?(newHome?'Ask about SAH/SHA eligibility and housing project review. HISA excludes new construction.':'Ask for clinical review and the HISA application process.'):'Ask which local agency can assess the barrier and screen for New York support.';const contact=coverage==='waiver'?'<p>Use your coordinator’s direct number. Ask which program can authorize the proposed change.</p>':va?'<p><a class="contact-action" href="https://www.va.gov/find-locations/?facilityType='+(newHome?'benefits':'health')+'" target="_blank" rel="noopener">Find your VA '+(newHome?'benefits office':'medical facility')+'</a></p>':'<p>'+phoneLink('800-342-9871')+'</p>';$('access-first').innerHTML='<article class="first-call"><span class="badge">Start here'+(county?' · '+esc(county)+' County, NY':'')+'</span><h3>'+esc(primary)+'</h3><p>'+esc(action)+'</p>'+contact+'</article><article><h3>Need help getting connected?</h3>'+(office?'<p><strong>'+esc(office.organization)+'</strong><br>'+phoneLink(office.phone)+'</p>':'<p>Choose a county above for veterans referral help.</p>')+(aging?'<p><strong>'+esc(aging.organization)+'</strong><br>'+phoneLink(aging.public_contact.phone)+'</p><p class="small"><a href="'+esc(aging.official_url)+'" target="_blank" rel="noopener">Aging contact source</a> · '+esc(aging.verification.last_reviewed_on)+'</p>':'')+'<p><strong>NY Connects statewide routing</strong><br>'+phoneLink('800-342-9871')+'</p></article>';$('access-steps').innerHTML='<h3>Your next three steps</h3><ol><li><strong>Make the first call.</strong> '+esc(action)+' Ask who handles follow-up.</li><li><strong>Prepare requested documents.</strong> '+(va&&!newHome&&coverage!=='waiver'?'For HISA, gather the prescription, Form 10-0103, owner permission, itemized estimate and before photograph. <a href="#hisa-checklist" id="open-hisa">Open the HISA checklist</a>.':'Ask about assessment, disability documentation, residency, income, owner consent and estimate requirements.')+'</li><li><strong>Confirm approval and remaining costs.</strong> Ask who approves work, which providers are accepted and how uncovered costs are handled.</li></ol>';const box=(title,body)=>'<article><h3>'+title+'</h3>'+body+'</article>';const parts=[];if(veteran!=='no'){parts.push(box('Veteran route: VA clinical review','<p>Ask Prosthetic and Sensory Aids Service about HISA. HISA excludes new construction; SAH/SHA have separate qualifying disability and ownership rules.</p><p><a href="https://www.va.gov/find-locations/?facilityType=health" target="_blank" rel="noopener">Find your VA medical facility</a></p>'));parts.push(box('New York veteran accessibility','<p>Access to Home for Heroes is administered through funded local partners. Confirm veteran status, disability, income and residence eligibility. Individuals cannot apply directly to HCR.</p>'));if(home==='family')parts.push(box('Temporary family home: ask about TRA','<p>Ask VA whether TRA applies; it requires SAH or SHA eligibility and temporary residence in a family member’s home.</p>'))}parts.push(box('New York: local assessment and funding partners','<p>NY Connects '+phoneLink('800-342-9871')+' can help identify the local referral. Access to Home and RESTORE use funded local administrators; confirm county coverage and resident intake. A program listing does not confirm available funds.</p>'));parts.push(box('Equipment loans and demonstrations','<p>Find the TRAID center serving your county. Ask about device trials, loans and suitable equipment. Ramp stock, installation and permanent equipment funding are not guaranteed.</p>'));if(coverage==='waiver')parts.push(box('Coordinate with your service plan','<p>Ask your coordinator which authorized service can address the barrier. Medicaid enrollment alone does not establish modification coverage.</p>'));if(home==='new')parts.push(box('Unfinished or new construction','<p>HISA excludes new construction. Do not assume repair or accessibility programs pay to finish a new house; ask each administrator before requesting estimates or committing funds.</p>'));if(home==='facility')parts.push(box('Returning home: coordinate before discharge','<p>Ask the discharge planner and the NHTD Regional Resource Development Center about eligibility and a safe community transition plan. A referral does not guarantee a waiver place or home modification.</p>'));if(home==='rent')parts.push(box('Rented home: confirm owner responsibilities','<p>Arrange owner permission and clarify any existing duty to provide accessibility changes. HISA requires notarized owner permission for renters; other programs have their own rules.</p>'));$('access-routing').innerHTML=parts.join('');const checklistLink=$('open-hisa');if(checklistLink)checklistLink.onclick=()=>{$('hisa-checklist').open=true};}"""
